parameters.text:
=You are a senior RAG infrastructure engineer investigating WHY a query scored low. Return ONLY valid JSON.

QUERY: {{ $json.question }}

ANSWER GIVEN: {{ $json.answer }}

JUDGE SCORES (1-5):
- relevance: {{ $json.relevance }}
- accuracy: {{ $json.accuracy }}
- completeness: {{ $json.completeness }}
- overall: {{ $json.overall }}

JUDGE RATIONALE: {{ $json.judge_rationale }}

RETRIEVED CHUNKS (top-{{ $json.retrieval_k }}, JSON):
{{ JSON.stringify($json.retrieved_chunks) }}

Return JSON exactly like:
{
  "root_cause": "one-paragraph hypothesis explaining the dimension(s) that scored lowest, grounded in the retrieved chunks vs the question intent",
  "recommended_fix": "one concrete actionable change (e.g. 'increase k to 8 to retrieve more changelog chunks', 'add a guardrail to refuse out-of-scope questions like ping', 'add a section to the corpus covering X')",
  "diagnosis": "full 2-3 sentence summary suitable for a morning report"
}

parameters.jsCode:
const failures = $('Find Failures').all();
const agentOutputs = $input.all();

return failures.map((f, i) => {
  const raw = agentOutputs[i]?.json?.output ?? agentOutputs[i]?.json?.text ?? '{}';
  let parsed = {};
  if (typeof raw === 'string') {
    try { parsed = JSON.parse(raw); } catch (e) { parsed = { diagnosis: raw }; }
  } else if (typeof raw === 'object') {
    parsed = raw;
  }

  return {
    json: {
      query_id: parseInt(f.json.query_id, 10),
      eval_run_id: parseInt(f.json.eval_run_id, 10),
      diagnosis: String(parsed.diagnosis ?? 'Agent returned no diagnosis').slice(0, 4000),
      root_cause: parsed.root_cause ?? null,
      recommended_fix: parsed.recommended_fix ?? null,
      tools_used: JSON.stringify([]),
      agent_model: 'gpt-4o',
      iterations: 1
    }
  };
});
